insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('8e7af5e6-5f79-5855-9a30-10c5f3362502','fe4ef061-bf23-5beb-912c-f91bdb025860','Practical skills technician','Maintains equipment and solves practical problems using tools and careful observation.','Choose an everyday object without dismantling it.',1,'{"title": "Sketch a repair plan", "minutes": 20, "steps": ["Choose an everyday object without dismantling it.", "Draw its parts and describe a problem it might develop.", "List the tools and safety questions a trained technician would consider."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('78cd36ab-bac6-5ffa-82c7-9664e2d7b515','fe4ef061-bf23-5beb-912c-f91bdb025860','Agricultural technician','Supports growing plants through practical observation, record keeping, and care of materials.','Look at a plant or a photograph of a garden.',2,'{"title": "Observe a growing space", "minutes": 20, "steps": ["Look at a plant or a photograph of a garden.", "Sketch a simple layout and list its light and water needs.", "Make a fictional one-week observation sheet; do not use chemicals or unfamiliar tools."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('1e075981-d0a9-5cf9-94ad-39ee2fb5b6b4','fe4ef061-bf23-5beb-912c-f91bdb025860','Solar installation technician','Helps trained teams plan, install, and maintain solar equipment. Electrical work requires appropriate training.','Draw a fictional building and mark where sunlight might reach it.',3,'{"title": "Plan on paper", "minutes": 20, "steps": ["Draw a fictional building and mark where sunlight might reach it.", "List questions about shade, weather, access, and safety.", "Prepare three questions for a qualified installer. Do not climb, wire, or handle electrical equipment."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('145e4e50-0bd5-5d46-b745-dbada46dd9c2','b8c86e6e-d7a3-59d4-a0bd-e7f5dc9c32db','Research assistant','Helps investigate questions by finding information, organizing observations, and checking evidence.','Choose a question such as why one room feels warmer.',1,'{"title": "Investigate an everyday question", "minutes": 20, "steps": ["Choose a question such as why one room feels warmer.", "Write two possible explanations and a safe observation that could distinguish them.", "Record what you would measure and what would remain uncertain."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('279c98de-22df-5092-9b82-8857d6a7d4fb','b8c86e6e-d7a3-59d4-a0bd-e7f5dc9c32db','Data analyst','Organizes information and looks for patterns that can help people make decisions.','Invent a table of seven days of travel times.',2,'{"title": "Explore a small dataset", "minutes": 20, "steps": ["Invent a table of seven days of travel times.", "Calculate the average and identify the shortest and longest trips.", "Write two observations and one reason the small sample might mislead you."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('785fd278-1463-5311-8cc1-e06436dfef48','b8c86e6e-d7a3-59d4-a0bd-e7f5dc9c32db','Software developer','Builds and improves digital tools by breaking problems into steps and testing solutions.','Choose a small problem such as remembering study tasks.',3,'{"title": "Design a simple tool", "minutes": 20, "steps": ["Choose a small problem such as remembering study tasks.", "Draw three screens on paper and describe what each button does.", "Ask a willing friend to follow the steps and note one improvement."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('8a44d176-5457-5aaa-b350-86422de76d06','3081c153-7803-5d7e-9346-42a62087a992','Content designer','Uses words and structure to make information easier to understand and act on.','Write a fictional notice for a student study group.',1,'{"title": "Make information clearer", "minutes": 20, "steps": ["Write a fictional notice for a student study group.", "Rewrite it so the purpose, time, and next action are easy to find.", "Ask a willing friend what they understood and revise one sentence."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('dab2e643-9045-5728-a258-b3738effc950','3081c153-7803-5d7e-9346-42a62087a992','Graphic designer','Combines images, typography, and layout to communicate ideas visually.','Choose a fictional school or community event.',2,'{"title": "Create a poster", "minutes": 20, "steps": ["Choose a fictional school or community event.", "Sketch a poster with one message and a clear next action.", "Try a second layout and compare which is easier to read."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('f6dc264e-5dd8-5e58-b0af-3c062206fcc6','3081c153-7803-5d7e-9346-42a62087a992','Video producer','Plans and combines images, sound, and stories to communicate through video.','Choose a harmless everyday topic you could explain in one minute.',3,'{"title": "Storyboard a short story", "minutes": 20, "steps": ["Choose a harmless everyday topic you could explain in one minute.", "Draw six frames with captions and a beginning, middle, and ending.", "Review the sequence without filming anyone; ask whether the story is clear."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('ab5a9130-1876-5cc0-b33f-5d9e51af8284','e970648c-dde8-5509-8817-af5344f2da3b','Community educator','Helps groups learn useful skills through explanations, demonstrations, and discussion.','Choose a skill you know well, such as folding paper.',1,'{"title": "Share a useful skill", "minutes": 20, "steps": ["Choose a skill you know well, such as folding paper.", "Plan a five-minute explanation in three steps.", "Teach a willing friend and ask which step could be clearer."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('319f7b7d-9516-50c1-83da-43cd36506bef','e970648c-dde8-5509-8817-af5344f2da3b','Teacher','Plans learning activities and supports learners as they practise and understand new ideas.','Pick a topic from a subject you enjoy.',2,'{"title": "Plan a mini lesson", "minutes": 20, "steps": ["Pick a topic from a subject you enjoy.", "Write a learning goal, a simple example, and one practice question.", "Try it with a willing peer and reflect on what helped them understand."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('3e397107-c181-5764-8a41-16adb0e839ab','e970648c-dde8-5509-8817-af5344f2da3b','Community support worker','Helps people find information and services, listens to concerns, and works with community teams.','Invent a student who needs help finding study information.',3,'{"title": "Map a fictional support journey", "minutes": 20, "steps": ["Invent a student who needs help finding study information.", "List respectful questions you could ask without collecting private details.", "Sketch the types of services they might need and what you would verify before referring them."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('e2957dad-6353-5622-8c89-99ce3a0f3b75','838001b4-2af5-5bac-9b97-241f809ed155','Project coordinator','Organizes people, tasks, and timelines to help a team complete a project.','Imagine a free study-circle meeting.',1,'{"title": "Plan a small event", "minutes": 20, "steps": ["Imagine a free study-circle meeting.", "List five tasks, who could do them, and a simple timeline.", "Identify one possible delay and describe a backup plan."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('91db69b6-5db0-5872-8e2c-deb0b534813b','838001b4-2af5-5bac-9b97-241f809ed155','Small business owner','Develops an offering, coordinates daily work, and makes decisions about customers and costs.','Invent a simple product or service for students.',2,'{"title": "Test a business idea on paper", "minutes": 20, "steps": ["Invent a simple product or service for students.", "Write who it might help and list fictional costs without spending money.", "Prepare three questions that would help test demand without promising sales."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('c5cec2eb-cf3b-5f6a-8e9a-351396b9e91a','838001b4-2af5-5bac-9b97-241f809ed155','Marketing coordinator','Helps communicate an organization’s offering and organize campaigns or events.','Choose a fictional learning event.',3,'{"title": "Draft an honest invitation", "minutes": 20, "steps": ["Choose a fictional learning event.", "Write two invitations for different audiences without exaggerated claims.", "Compare their clarity and list how you could measure interest respectfully."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('4dac014b-e541-5dc5-ae16-593a4d0f5339','91822814-4759-520f-b167-8e064cf651fc','Records coordinator','Keeps documents and information organized, accurate, and easy to retrieve.','Create ten fictional document names with dates.',1,'{"title": "Organize sample records", "minutes": 20, "steps": ["Create ten fictional document names with dates.", "Choose a folder and naming system that another person could understand.", "Find duplicate or missing entries and write one checking rule."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('6b9c09bc-0cc1-5927-8c2a-7d4bf90b2f14','91822814-4759-520f-b167-8e064cf651fc','Accounting assistant','Helps organize financial records, check calculations, and prepare information for review.','Invent five income or expense entries for a study group.',2,'{"title": "Check a fictional budget", "minutes": 20, "steps": ["Invent five income or expense entries for a study group.", "Calculate totals and check a deliberately duplicated entry.", "Explain how you would keep a clear record without using anyone\u2019s real financial information."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
insert into career_roles (id,category_id,title,description,suggested_next_step,display_order,activity,is_demo) values ('cd83ba99-4586-5dbe-b70a-61a812d053e2','91822814-4759-520f-b167-8e064cf651fc','Logistics administrator','Tracks supplies, schedules, and documents to help goods or materials reach their destinations.','Create a list of five imaginary book deliveries.',3,'{"title": "Plan a fictional delivery", "minutes": 20, "steps": ["Create a list of five imaginary book deliveries.", "Make a table of destinations, dates, and quantities.", "Check for missing information and describe how you would handle one delay."]}'::jsonb,true) on conflict (id) do update set title=excluded.title,description=excluded.description,suggested_next_step=excluded.suggested_next_step,display_order=excluded.display_order,activity=excluded.activity where career_roles.is_demo;
